import{_ as n,c as i,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Sehen Sie genau, was sich geändert hat","description":"","frontmatter":{"layout":"home","title":"Sehen Sie genau, was sich geändert hat","hero":{"name":"qDiff","text":"Sehen Sie genau, was sich geändert hat","tagline":"Vergleichen Sie zwei Dateien, zwei Ordner oder die Änderungen in einem Projekt — nebeneinander, in Farbe und ohne Rätselraten. Alles bleibt auf Ihrem Mac.","image":{"src":"/hero-illustration.png","alt":"qDiff vergleicht zwei Dateien"}},"features":[{"icon":{"light":"/icons/files.svg","dark":"/icons/files-dark.svg","alt":"Dateien","width":"24","height":"24"},"title":"Dateien vergleichen","details":"Öffnen Sie zwei oder drei Dateien nebeneinander. Geänderte Zeilen sind eingefärbt, und selbst ein einzelnes geändertes Wort wird hervorgehoben — Sie müssen dieselbe Zeile nicht zweimal lesen.","link":"/guide/files","linkText":"Mehr erfahren"},{"icon":{"light":"/icons/folders.svg","dark":"/icons/folders-dark.svg","alt":"Ordner","width":"24","height":"24"},"title":"Ganze Ordner vergleichen","details":"Sehen Sie einen kompletten Ordnerbaum auf einen Blick: was neu ist, was sich geändert hat und was fehlt. Filtern Sie nach Status und kopieren oder synchronisieren Sie Dateien direkt aus der Liste.","link":"/guide/folders","linkText":"Mehr erfahren"},{"icon":{"light":"/icons/review.svg","dark":"/icons/review-dark.svg","alt":"Projekte","width":"24","height":"24"},"title":"Vor dem Commit prüfen","details":"Öffnen Sie einen Projektordner, um jede bearbeitete Datei zu sehen, jede Änderung zu lesen und den Commit im selben Fenster abzuschließen.","link":"/guide/projects","linkText":"Mehr erfahren"},{"icon":{"light":"/icons/images.svg","dark":"/icons/images-dark.svg","alt":"Bilder","width":"24","height":"24"},"title":"Auch Bilder und Archive","details":"Stellen Sie zwei Bilder nebeneinander oder legen Sie sie übereinander, um Unterschiede zu erkennen. Zip- und tar-Archive öffnen sich direkt als Ordnervergleich — ohne Entpacken.","link":"/guide/more","linkText":"Mehr erfahren"},{"icon":{"light":"/icons/navigate.svg","dark":"/icons/navigate-dark.svg","alt":"Navigation","width":"24","height":"24"},"title":"Nie den Überblick verlieren","details":"Beide Seiten scrollen gemeinsam, eine anklickbare Übersicht zeigt, wo Sie sich befinden, und ein Tastendruck springt zur nächsten Änderung — selbst in einem langen Dokument.","link":"/guide/files","linkText":"Mehr erfahren"},{"icon":{"light":"/icons/privacy.svg","dark":"/icons/privacy-dark.svg","alt":"Datenschutz","width":"24","height":"24"},"title":"Von Grund auf privat","details":"Kein Konto, kein Upload, kein Tracking. qDiff öffnet nur die Dateien, die Sie auswählen, und Sie können einen Vergleich als Bild speichern, um ihn zu teilen.","link":"/privacy/","linkText":"Unser Versprechen"}],"sections":{"featuresTitle":"Alles, was Sie brauchen, um Unterschiede zu sehen","featuresSubtitle":"Öffnen Sie zwei Dinge, und qDiff zeigt klar und unaufdringlich, was sich geändert hat.","categoriesTitle":"Wo qDiff hilft","categoriesSubtitle":"Die Momente, in denen die Frage „Was hat sich geändert?“ wirklich zählt","howTitle":"Drei Schritte, keine Einrichtung","howSubtitle":"Von zwei Dateien zu einer klaren Antwort","faqTitle":"Gut zu wissen","faqSubtitle":"Kurze Antworten, bevor Sie herunterladen"},"categoriesCta":"qDiff holen","cta":{"title":"Hören Sie auf zu raten, was sich geändert hat.","description":"Laden Sie qDiff für Ihren Mac und stellen Sie zwei Versionen nebeneinander. Kostenlos nutzbar, und Ihre Dateien verlassen niemals Ihren Computer.","primary":"qDiff holen","primaryLink":"/guide/download","secondary":"Anleitung lesen","secondaryLink":"/guide/introduction"},"categories":[{"name":"Korrekturlesen","badge":"KL","desc":"Zwei Entwürfe, ein geänderter Satz","color":"#3b82f6","link":"/guide/files"},{"name":"Sicherungen","badge":"SI","desc":"Prüfen, ob eine Kopie wirklich übereinstimmt","color":"#20a877","link":"/guide/folders"},{"name":"Code-Review","badge":"CR","desc":"Jede Änderung vor dem Commit lesen","color":"#6366f1","link":"/guide/projects"},{"name":"Fotos","badge":"FO","desc":"Das unpassende Bild finden","color":"#0ea5e9","link":"/guide/more"},{"name":"Neue Lieferungen","badge":"NL","desc":"Sehen, was die andere Seite geändert hat","color":"#f59e0b","link":"/guide/files"},{"name":"Teilen","badge":"TE","desc":"Ein Bild der Unterschiede verschicken","color":"#14b8a6","link":"/guide/more"}],"steps":[{"num":"01","title":"Zwei Dinge öffnen","desc":"Ziehen Sie zwei Dateien oder Ordner auf qDiff oder wählen Sie einen Projektordner, den Sie prüfen möchten."},{"num":"02","title":"Die Farben lesen","desc":"Geänderte Zeilen und Wörter sind markiert; klicken Sie auf die Übersicht oder drücken Sie eine Taste, um zwischen Änderungen zu springen."},{"num":"03","title":"Handeln oder teilen","desc":"Bearbeiten, kopieren, ersetzen oder synchronisieren Sie direkt hier und speichern Sie ein Bild, wenn es jemand anderes sehen soll."}],"faqs":[{"question":"Ist qDiff kostenlos?","answer":"Ja. Jeder Vergleich funktioniert ohne Bezahlung. Die kostenlose Version zeigt lediglich einen „Nicht lizenziert“-Hinweis in der Tableiste; ein einmaliger Kauf entfernt ihn und schließt alle künftigen Premium-Extras ein. Es gibt kein Abo."},{"question":"Welche Macs werden unterstützt?","answer":"macOS 12 oder neuer, sowohl auf Macs mit Apple-Chip als auch mit Intel-Prozessor."},{"question":"Brauche ich ein Konto oder eine Internetverbindung?","answer":"Nein. qDiff arbeitet offline und öffnet nur die Dateien, die Sie auswählen. Nichts wird hochgeladen."},{"question":"Kann es ganze Ordner vergleichen?","answer":"Ja. Sie erhalten eine Baumansicht mit neuen, geänderten und fehlenden Dateien, Statusfiltern sowie Kopier- und Synchronisierungsaktionen direkt in der Liste."},{"question":"Gibt es die Oberfläche auch auf Deutsch und in anderen Sprachen?","answer":"Ja — Englisch, vereinfachtes Chinesisch, traditionelles Chinesisch, Japanisch, Deutsch, Spanisch und Französisch, jeweils in heller und dunkler Darstellung."},{"question":"Was geschieht mit meinen Dateien?","answer":"Sie bleiben auf Ihrem Mac. Wir sammeln, verfolgen oder synchronisieren sie nicht. Die vollständigen Details finden Sie in der Datenschutzerklärung."}]},"headers":[],"relativePath":"de/index.md","filePath":"de/index.md","lastUpdated":1794296122000}'),a={name:"de/index.md"};function s(d,e,l,o,h,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="eine-app-fur-alle-„was-hat-sich-geandert-fragen" tabindex="-1">Eine App für alle „Was hat sich geändert?“-Fragen <a class="header-anchor" href="#eine-app-fur-alle-„was-hat-sich-geandert-fragen" aria-label="Permalink to &quot;Eine App für alle „Was hat sich geändert?“-Fragen&quot;">​</a></h2><p>qDiff stellt zwei Versionen nebeneinander und macht das Lesen angenehm: <strong>farbig markierte Änderungen</strong>, <strong>Hervorhebungen bis hin zu einem einzelnen Wort</strong> und <strong>eine kleine Übersicht, die Sie anklicken können</strong>. Es funktioniert mit Dateien, ganzen Ordnern, Bildern, Archiven und Projektordnern.</p><ul><li><strong>Ihre Dateien bleiben Ihre</strong> — kein Konto, kein Upload, kein Tracking.</li><li><strong>Kostenlos nutzbar</strong> — jeder Vergleich funktioniert ohne Kauf.</li><li><strong>Für den Mac gemacht</strong> — helle und dunkle Darstellung, Oberfläche in sieben Sprachen.</li></ul><blockquote><p>Ziehen Sie zwei Dateien ins Fenster, und schon sind Sie fertig. <a href="./guide/introduction.html">So funktioniert es</a>.</p></blockquote>',4)])])}const f=n(a,[["render",s]]);export{g as __pageData,f as default};
